WHAT ABOUT THIS CODE THAT CAN CORRECT THE STUDY IN THE SCHEDULE WHICH USES STUDY INSTEAD OF THE NAME OF THE SUBJECT OR THE COURSE NAME

import { GoogleGenAI, HarmCategory, HarmBlockThreshold, GenerateContentResponse, Type } from "@google/genai";
import type { UserDetails, Lecture, StudyGoal, AgendaItem, SmartPlan, ImagePart, QuizQuestion, QuizType, ChatTurn } from '../types';

// ============================================
// PERFORMANCE OPTIMIZATIONS
// ============================================

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY! });

const safetySettings = [
    { category: HarmCategory.HARM_CATEGORY_HARASSMENT, threshold: HarmBlockThreshold.BLOCK_NONE },
    { category: HarmCategory.HARM_CATEGORY_HATE_SPEECH, threshold: HarmBlockThreshold.BLOCK_NONE },
    { category: HarmCategory.HARM_CATEGORY_SEXUALLY_EXPLICIT, threshold: HarmBlockThreshold.BLOCK_NONE },
    { category: HarmCategory.HARM_CATEGORY_DANGEROUS_CONTENT, threshold: HarmBlockThreshold.BLOCK_NONE },
];

class ResponseCache {
    private cache = new Map<string, { data: any; expiry: number }>();
    private readonly TTL = 30000;

    get(key: string): any | null {
        const cached = this.cache.get(key);
        if (!cached || Date.now() > cached.expiry) {
            this.cache.delete(key);
            return null;
        }
        return cached.data;
    }

    set(key: string, data: any): void {
        this.cache.set(key, { data, expiry: Date.now() + this.TTL });
        if (this.cache.size > 100) {
            const oldest = Array.from(this.cache.entries())[0];
            this.cache.delete(oldest[0]);
        }
    }

    clear(): void {
        this.cache.clear();
    }
}

const cache = new ResponseCache();

// ============================================
// OPTIMIZED SCHEMAS
// ============================================

const planSlotSchema = {
    type: Type.OBJECT,
    properties: {
        activity: { type: Type.STRING },
        startTime: { type: Type.STRING },
        endTime: { type: Type.STRING },
        type: { type: Type.STRING },
        link: { type: Type.STRING },
        code: { type: Type.STRING },
        isLocked: { type: Type.BOOLEAN },
        durationMinutes: { type: Type.NUMBER },
        location: { type: Type.STRING },
    },
    required: ['activity', 'startTime', 'endTime', 'type']
};

const smartPlanSchema = {
    type: Type.ARRAY,
    items: {
        type: Type.OBJECT,
        properties: {
            day: { type: Type.STRING },
            slots: { type: Type.ARRAY, items: planSlotSchema }
        },
        required: ['day', 'slots']
    }
};

const quizSchema = {
    type: Type.ARRAY,
    items: {
        type: Type.OBJECT,
        properties: {
            question: { type: Type.STRING },
            options: { type: Type.ARRAY, items: { type: Type.STRING } },
            correctAnswer: { type: Type.STRING },
            explanation: { type: Type.STRING },
            topic: { type: Type.STRING },
            type: { type: Type.STRING },
        },
        required: ['question', 'correctAnswer', 'explanation', 'topic', 'type']
    }
};

const graphSolutionSchema = {
    type: Type.OBJECT,
    properties: {
        explanation: { type: Type.STRING },
        graphFunction: { type: Type.STRING },
        suggestedTitle: { type: Type.STRING },
    },
    required: ['explanation', 'graphFunction']
};

const tableSchema = {
    type: Type.OBJECT,
    properties: {
        title: { type: Type.STRING },
        headers: { type: Type.ARRAY, items: { type: Type.STRING } },
        rows: { type: Type.ARRAY, items: { type: Type.ARRAY, items: { type: Type.STRING } } },
        caption: { type: Type.STRING }
    },
    required: ['headers', 'rows']
};

// ============================================
// FAST PARSER WITH ERROR RECOVERY
// ============================================

const parseGeminiResponse = <T>(response: GenerateContentResponse, fallback?: T): T => {
    try {
        const text = response.text.trim();

        let jsonStr = text;
        if (text.startsWith('```')) {
            const start = text.indexOf('{') || text.indexOf('[');
            const end = text.lastIndexOf('}') || text.lastIndexOf(']');
            jsonStr = text.substring(start, end + 1);
        }

        return JSON.parse(jsonStr) as T;
    } catch (e) {
        console.error("❌ Parse error:", e, "Response:", response.text.substring(0, 200));
        if (fallback) return fallback;
        throw new Error("AI response parsing failed. Please try again.");
    }
};

// ============================================
// OPTIMIZED MODEL SELECTOR
// ============================================

const getOptimalModel = (task: 'fast' | 'balanced' | 'quality'): string => {
    switch (task) {
        case 'fast': return 'gemini-2.0-flash-exp';
        case 'balanced': return 'gemini-2.0-flash-exp';
        case 'quality': return 'gemini-2.0-flash-exp';
        default: return 'gemini-2.0-flash-exp';
    }
};

// ============================================
// SMART PLAN GENERATION (FIXED)
// ============================================

export const generateSmartPlan = async (
    userDetails: UserDetails,
    lectures: Lecture[],
    studyGoals: StudyGoal[],
    agendaItems: AgendaItem[],
    generalGoals: string,
    existingPlan?: SmartPlan
): Promise<SmartPlan> => {
    const cacheKey = `plan_${JSON.stringify({ lectures, studyGoals, agendaItems, generalGoals }).substring(0, 100)}`;
    const cached = cache.get(cacheKey);
    if (cached) {
        console.log('✅ Using cached plan');
        return cached;
    }

    const isRegeneration = !!existingPlan;

    // FIXED: Enhanced prompt with explicit examples and strict rules
    const prompt = `Create a weekly study plan in JSON format.

**User Context:**
${JSON.stringify({ userDetails, lectures, studyGoals, agendaItems, generalGoals }, null, 2)}

${isRegeneration ? `**Modify existing plan:**\n${JSON.stringify(existingPlan, null, 2)}` : ''}

**Critical Requirements:**

1. **ACTIVITY NAMING (MOST IMPORTANT):**
   - For 'study' type slots: activity MUST be the EXACT course/subject name
   - ✅ CORRECT: "MATH 382", "Biochemistry", "Computer Science 101"
   - ❌ WRONG: "Study", "Revision", "Study Session", "Study Time"
   - If a study goal is for "Mathematics", the activity should be "Mathematics"
   - If a lecture is "CHEM 201", related study should be "CHEM 201"
   - NEVER use generic words like "Study" or "Revision" as the activity name

2. **Slot Types:**
   - 'lecture': From lectures list, lock them (isLocked: true)
   - 'study': For study goals, use SPECIFIC subject names
   - 'agenda': From agenda items, lock them (isLocked: true)
   - 'break': Short breaks (10-15 min)
   - 'free': Unallocated time

3. **Format:**
   - 7 days (Monday through Sunday)
   - Times in "HH:MM AM/PM" format (e.g., "8:00 AM", "2:30 PM")
   - Include 'code' field for courses if available
   - Include 'location' field for lectures if available

4. **Study Session Rules:**
   - Schedule study sessions to meet weekly hour goals
   - Place study sessions at optimal times (not late at night)
   - Study sessions should be 1-3 hours long
   - Add 10-minute breaks between long study sessions

**Example of CORRECT 'study' slot:**
{
  "activity": "MATH 382",
  "startTime": "8:00 AM",
  "endTime": "9:00 AM",
  "type": "study",
  "code": "MATH 382"
}

**Example of WRONG 'study' slot:**
{
  "activity": "Study",  ❌ NEVER DO THIS
  "startTime": "8:00 AM",
  "endTime": "9:00 AM",
  "type": "study"
}

Return ONLY the JSON array. No explanations.`;

    const response = await ai.models.generateContent({
        model: getOptimalModel('fast'),
        contents: prompt,
        config: {
            responseMimeType: 'application/json',
            responseSchema: smartPlanSchema,
            temperature: 0.3, // Lower temperature for more consistent output
            safetySettings,
        },
    });

    const plan = parseGeminiResponse<SmartPlan>(response, []);

    // POST-PROCESSING: Ensure no generic "Study" activities
    const fixedPlan = plan.map(dayPlan => ({
        ...dayPlan,
        slots: dayPlan.slots.map(slot => {
            // If it's a study slot with generic name, try to fix it
            if (slot.type === 'study' && (
                slot.activity.toLowerCase() === 'study' ||
                slot.activity.toLowerCase() === 'revision' ||
                slot.activity.toLowerCase().includes('study session')
            )) {
                // Try to match with a study goal
                const matchingGoal = studyGoals.find(goal => 
                    // Not yet assigned in this time slot
                    !dayPlan.slots.some(s => 
                        s.activity === goal.subject && 
                        s !== slot
                    )
                );

                if (matchingGoal) {
                    console.warn(`⚠️ Fixed generic study slot to: ${matchingGoal.subject}`);
                    return { ...slot, activity: matchingGoal.subject };
                }

                // Fallback: use first study goal or mark as "Unassigned Study"
                const fallbackSubject = studyGoals[0]?.subject || 'General Study';
                console.warn(`⚠️ Fixed generic study slot to: ${fallbackSubject}`);
                return { ...slot, activity: fallbackSubject };
            }
            return slot;
        })
    }));

    cache.set(cacheKey, fixedPlan);
    return fixedPlan;
};

// ============================================
// IMAGE-BASED PLAN (FIXED)
// ============================================

export const generatePlanFromImage = async (
    userDetails: UserDetails,
    studyGoals: StudyGoal[],
    agendaItems: AgendaItem[],
    generalGoals: string,
    image: ImagePart,
    existingPlan?: SmartPlan
): Promise<SmartPlan> => {
    // FIXED: Enhanced prompt for image-based plans
    const prompt = `Extract the timetable from this image and create a weekly study plan in JSON format.

**User Context:**
${JSON.stringify({ userDetails, studyGoals, agendaItems, generalGoals }, null, 2)}

**Critical Requirements:**

1. **ACTIVITY NAMING (MOST IMPORTANT):**
   - Extract course codes and names from the image
   - For 'lecture' slots: Use the exact course name from image (e.g., "MATH 382")
   - For 'study' slots: Use the SPECIFIC course name, NEVER generic "Study"
   - ✅ CORRECT: "MATH 382", "Biochemistry", "CS 101"
   - ❌ WRONG: "Study", "Revision", "Study Session"

2. **Extract from image:**
   - Course codes, names, times, locations
   - Lock all extracted lectures (isLocked: true)

3. **Add study sessions:**
   - Based on study goals provided
   - Use SPECIFIC subject names for activity
   - Schedule around extracted lectures

4. **Format:**
   - Times: "HH:MM AM/PM"
   - Include 'code' and 'location' fields where available

**Example:**
If image shows "MATH 382, 8:00-9:00, Room 201":
{
  "activity": "MATH 382",
  "code": "MATH 382",
  "startTime": "8:00 AM",
  "endTime": "9:00 AM",
  "type": "lecture",
  "location": "Room 201",
  "isLocked": true
}

Return ONLY JSON array.`;

    const response = await ai.models.generateContent({
        model: 'gemini-2.0-flash-exp',
        contents: { parts: [{ text: prompt }, image] },
        config: {
            responseMimeType: 'application/json',
            responseSchema: smartPlanSchema,
            temperature: 0.3,
            safetySettings,
        },
    });

    const plan = parseGeminiResponse<SmartPlan>(response, []);

    // POST-PROCESSING: Same fix as above
    const fixedPlan = plan.map(dayPlan => ({
        ...dayPlan,
        slots: dayPlan.slots.map(slot => {
            if (slot.type === 'study' && (
                slot.activity.toLowerCase() === 'study' ||
                slot.activity.toLowerCase() === 'revision'
            )) {
                const matchingGoal = studyGoals.find(goal => 
                    !dayPlan.slots.some(s => s.activity === goal.subject && s !== slot)
                );

                if (matchingGoal) {
                    return { ...slot, activity: matchingGoal.subject };
                }

                return { ...slot, activity: studyGoals[0]?.subject || 'General Study' };
            }
            return slot;
        })
    }));

    return fixedPlan;
};

// ============================================
// FAST IMAGE CLASSIFICATION
// ============================================

export const isImageTimetable = async (image: ImagePart): Promise<boolean> => {
    const cacheKey = `timetable_check_${image.inlineData.data.substring(0, 50)}`;
    const cached = cache.get(cacheKey);
    if (cached !== null) return cached;

    const response = await ai.models.generateContent({
        model: getOptimalModel('fast'),
        contents: { parts: [{ text: "Timetable? true/false" }, image] },
        config: { safetySettings },
    });

    const result = response.text.trim().toLowerCase().includes('true');
    cache.set(cacheKey, result);
    return result;
};

