    context: string,
    numQuestions: number,
    quizType: QuizType,
    focusArea: string
): Promise<QuizQuestion[]> => {
    const prompt = `Generate ${numQuestions} ${quizType} questions.
Context: ${context.substring(0, 10000)}
${focusArea ? `Focus: ${focusArea}` : ''}
Output: JSON QuizQuestion[]
Rules: MCQ has options. Theory has no options.
ONLY JSON`;

    const response = await ai.models.generateContent({
        model: getOptimalModel('fast'),
        contents: prompt,
        config: { 
            responseMimeType: 'application/json',
            responseSchema: quizSchema,
            safetySettings 
        },
    });

    return parseGeminiResponse<QuizQuestion[]>(response, []);
};

// ============================================
// PROBLEM SOLVER (OPTIMIZED)
// ============================================

export const solveProblem = async (
    questionText: string,
    imagePart: ImagePart | null,
    outputFormat: string,
    programmingLanguage: string,
    graphInterval?: string,
    graphYInterval?: string,
): Promise<string> => {
    let prompt = `Solve: ${questionText}\nFormat: ${outputFormat}\n`;

    if (outputFormat === 'code') {
        prompt += `Lang: ${programmingLanguage}. Markdown code block only.`;
    } else if (outputFormat === 'graph') {
        prompt += `JSON: {explanation, graphFunction (e.g. "x^2"), suggestedTitle}. ${graphInterval ? `X: ${graphInterval}` : ''}`;
    } else {
        prompt += `Markdown + LaTeX.`;
    }

    const contents: any = { parts: [{ text: prompt }] };
    if (imagePart) contents.parts.push(imagePart);

    const response = await ai.models.generateContent({
        model: getOptimalModel('quality'),
        contents,
        config: {
            ...(outputFormat === 'graph' ? { 
                responseMimeType: 'application/json',
                responseSchema: graphSolutionSchema
            } : {}),
            safetySettings,
        },
    });

    return response.text.trim();
};

