import React, { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
import { useBreakContext } from '../context/BreakContext';
import { generateActivityOptions } from '../utils/generateActivityOptions';

const BREAK_LENGTH = 15; // minutes

interface ActivityOption {
    label: string;
    value: string;
}

const BreakView: React.FC = () => {
    const router = useRouter();
    const { breakData, setBreakData, isBreak, setIsBreak } = useBreakContext();
    const [selectedActivity, setSelectedActivity] = useState<string>('');
    const [activityOptions, setActivityOptions] = useState<ActivityOption[]>([]);
    const [timeLeft, setTimeLeft] = useState(BREAK_LENGTH * 60);

    useEffect(() => {
        const generatedOptions = generateActivityOptions();
        setActivityOptions(generatedOptions);
    }, []);

    useEffect(() => {
        if (isBreak) {
            const timer = setInterval(() => {
                setTimeLeft((prevTime) => prevTime - 1);
            }, 1000);

            if (timeLeft === 0) {
                clearInterval(timer);
                setIsBreak(false);
                router.push('/');
            }

            return () => clearInterval(timer);
        }
    }, [isBreak, timeLeft, router, setIsBreak]);

    const handleStartBreak = () => {
        if (selectedActivity) {
            setBreakData({
                ...breakData,
                activity: selectedActivity,
                startTime: Date.now(),
            });
            setIsBreak(true);
            setTimeLeft(BREAK_LENGTH * 60);
        }
    };

    const handleSelectChange = (event: React.ChangeEvent<HTMLSelectElement>) => {
        setSelectedActivity(event.target.value);
    };

    const isWalkingActivity = selectedActivity.toLowerCase().includes('walk');

    return (
        <div className="flex flex-col items-center justify-center h-screen bg-gray-100">
            {isBreak ? (
                <>
                    <h1 className="text-3xl font-bold mb-4">Break Time!</h1>
                    <p className="text-xl mb-4">
                        Time remaining: {Math.floor(timeLeft / 60)}:
                        {(timeLeft % 60).toString().padStart(2, '0')}
                    </p>
                    {isWalkingActivity ? (
                        <WalkingPersonAnimation />
                    ) : (
                        <RelaxAnimation />
                    )}
                </>
            ) : (
                <>
                    <h1 className="text-3xl font-bold mb-4">Take a Break</h1>
                    <select
                        onChange={handleSelectChange}
                        className="p-2 border rounded"
                    >
                        <option value="">Select an activity</option>
                        {activityOptions.map((option) => (
                            <option key={option.value} value={option.value}>
                                {option.label}
                            </option>
                        ))}
                    </select>
                    <button
                        onClick={handleStartBreak}
                        className="mt-4 bg-blue-500 hover:bg-blue-700 text-white font-bold py-2 px-4 rounded"
                        disabled={!selectedActivity}
                    >
                        Start Break
                    </button>
                </>
            )}
        </div>
    );
};

const WalkingPersonAnimation: React.FC = () => {
    return (
        <div className="walking-person-container">
            <div className="walking-person"></div>
            <style jsx>{`
                .walking-person-container {
                    width: 200px;
                    height: 200px;
                    position: relative;
