These rules introduce **File Size Validation** (to match your 50MB frontend limit) and strict **Authentication Checks**.

### Copy and Paste into Firebase Console > Storage > Rules

```javascript
rules_version = '2';
service firebase.storage {
  match /b/{bucket}/o {

    // --- Helper Functions ---

    // Check if user is logged in
    function isAuthenticated() {
      return request.auth != null;
    }

    // Check if user matches the folder name
    function isOwner(userId) {
      return isAuthenticated() && request.auth.uid == userId;
    }

    // Enforce file size limit (e.g., 50MB to match your frontend logic)
    function isValidSize() {
      return request.resource.size < 50 * 1024 * 1024; 
    }

    // --- Rules ---

    // 1. Collaborative Sessions
    // Used by: CollaborativeSession.tsx
    // Path: sessions/{sessionCode}/{fileName}
    match /sessions/{sessionCode}/{allPaths=**} {
      // Anyone logged in can read session files (needed to see what others share)
      allow read: if isAuthenticated();

      // Anyone logged in can upload, BUT we enforce size limits
      allow write: if isAuthenticated() && isValidSize();
    }

    // 2. User Private Folder
    // (Good practice for future features if you move away from Base64 profile pics)
    match /users/{userId}/{allPaths=**} {
      allow read, write: if isOwner(userId);
    }

    // 3. Feedback Images
    // Path: feedback/{fileName}
    match /feedback/{allPaths=**} {
      // Admins only (conceptually) - implies you check this in console
      allow read: if false; 

      // Logged in users can upload evidence for bugs
      allow write: if isAuthenticated() && isValidSize();
    }

    // 4. Block everything else
    match /{allPaths=**} {
      allow read, write: if false;
    }
  }
}
