const SESSION_TOKEN_KEY = 'sessionToken';

type UserRecord = UserDetails & { id: string; password?: string };

// Local storage helper for fallback auth
const getLocalUsers = (): UserRecord[] => {
    return storageService.loadItem<UserRecord[]>('users') || [];
};

const saveLocalUsers = (users: UserRecord[]) => {
    storageService.saveItem('users', users);
};

const createToken = (user: UserDetails & { id: string }): string => {
    try {
        return btoa(JSON.stringify(user));
    } catch (e) {
        const jsonStr = JSON.stringify(user);
        const uint8Array = new TextEncoder().encode(jsonStr);
        let binaryString = '';
        uint8Array.forEach((byte) => {
            binaryString += String.fromCharCode(byte);
        });
        return btoa(binaryString);
    }
};

const decodeToken = (token: string): UserDetails & { id: string } | null => {
    try {
        return JSON.parse(atob(token));
    } catch (e) {
        try {
            const binaryString = atob(token);
            const uint8Array = new Uint8Array(binaryString.length);
            for (let i = 0; i < binaryString.length; i++) {
                uint8Array[i] = binaryString.charCodeAt(i);
            }
            const jsonStr = new TextDecoder().decode(uint8Array);
            return JSON.parse(jsonStr);
        } catch (err) {
            return null;
        }
    }
};

