export const signUp = async (
    name: string,
    email: string,
    password_param: string,
    recoveryQuestion: string,
    recoveryAnswer: string
): Promise<UserDetails> => {
    return new Promise(async (resolve, reject) => {
        try {
            // 1. Check Local Duplicates first
            const localUsers = getLocalUsers();
            if (localUsers.some(user => user.email === email)) {
                reject(new Error('Email already registered locally'));
                return;
            }

            let firebaseUid: string;
            let isCloudEnabled = false;

            // 2. Try Firebase Auth
            try {
                const userCredential = await auth.createUserWithEmailAndPassword(email, password_param);
                firebaseUid = userCredential.user!.uid;
                isCloudEnabled = true;
            } catch (error: any) {
                console.warn("Firebase SignUp failed, falling back to local:", error.message);
                if (error.code === 'auth/email-already-in-use') {
                    reject(new Error('Email already registered'));
                    return;
                }
                // Fallback to local ID
                firebaseUid = `local_${Date.now()}`;
            }

            // 3. Construct User Profile
            const newUserProfile: UserRecord = {
                id: firebaseUid,
                name,
                email,
                educationalLevel: EducationalLevel.UNDERGRADUATE,
                subscriptionTier: 'premium',
                subscriptionStatus: 'active',
                usage: initializeUsage(),
                recoveryQuestion,
                recoveryAnswer,
                password: password_param // Store locally for fallback auth
            };

            // 4. Save Locally (Critical for fallback)
            localUsers.push(newUserProfile);
            saveLocalUsers(localUsers);

            // 5. Try Cloud Sync if enabled
            if (isCloudEnabled) {
                try {
                    // Don't save password to cloud
                    const { password, ...cloudProfile } = newUserProfile;
                    await db.collection('users').doc(firebaseUid).set({
                        userDetails: cloudProfile,
                        createdAt: firebase.firestore.FieldValue.serverTimestamp()
                    });
                } catch (e) {
                    console.warn("Cloud Firestore save failed:", e);
                }
            }

            // 6. Create Session
            const { password, ...userSession } = newUserProfile;
            const token = createToken(userSession as UserDetails & { id: string });
            storageService.saveItem(SESSION_TOKEN_KEY, token);

            resolve(userSession as UserDetails);
        } catch (error: any) {
            console.error("Sign Up Error", error);
            reject(new Error(error.message || 'Failed to sign up'));
        }
    });
};

export const login = async (email: string, password_param: string): Promise<UserDetails> => {
    return new Promise(async (resolve, reject) => {
        let userProfile: UserDetails & { id: string } | null = null;
        let isCloudLogin = false;

        // 1. Try Firebase Login
        try {
            const userCredential = await auth.signInWithEmailAndPassword(email, password_param);
            const firebaseUid = userCredential.user!.uid;

            // Try to fetch profile from Firestore
            const doc = await db.collection('users').doc(firebaseUid).get();

            if (doc.exists) {
                const data = doc.data();
                userProfile = { ...data?.userDetails, id: firebaseUid };

                // Sync Cloud Data to Local Storage
                if (data?.smartPlan) storageService.saveItem('smartPlan', data.smartPlan);
                if (data?.notes) storageService.saveItem('notes', data.notes);
                if (data?.savedTimetables) storageService.saveItem('savedTimetables', data.savedTimetables);
                if (data?.trackedData) storageService.saveItem('trackedData', data.trackedData);

                isCloudLogin = true;
            }
        } catch (error: any) {
            console.warn("Firebase Login failed, attempting local fallback:", error.message);
            // If it's a wrong password specifically from Firebase, stop here.
            if (error.code === 'auth/wrong-password') {
                reject(new Error('Invalid email or password'));
                return;
            }
            // For invalid-credential, user-not-found, or network errors, try local fallback
        }

        // 2. Local Fallback if Cloud Login didn't yield a profile
        if (!userProfile) {
            const localUsers = getLocalUsers();
            const localUser = localUsers.find(u => u.email === email && u.password === password_param);

            if (localUser) {
                const { password, ...safeUser } = localUser;
                userProfile = safeUser as UserDetails & { id: string };
            }
        }

        if (userProfile) {
             // 3. Create Session
            const token = createToken(userProfile);
            storageService.saveItem(SESSION_TOKEN_KEY, token);
            resolve(userProfile);
        } else {
            reject(new Error('Invalid email or password'));
        }
    });
};

