// ============================================
// PERFORMANCE-OPTIMIZED INTERFACES
// ============================================

interface GlobalStats {
    totalRatings: number;
    totalRatingSum: number;
    totalComments: number;
    activeUsers: number;
    studyMaterials: number;
    lastUpdated?: number;
}

interface Comment {
    id: string;
