// ============================================
// CACHE LAYER (CRITICAL FOR PERFORMANCE)
// ============================================

class CacheManager {
    private cache = new Map<string, { data: any; expiry: number }>();
    private readonly TTL = 30000; // 30 seconds cache

    set(key: string, data: any, ttl: number = this.TTL): void {
        this.cache.set(key, {
            data,
            expiry: Date.now() + ttl
        });
    }

    get(key: string): any | null {
        const cached = this.cache.get(key);
        if (!cached) return null;

        if (Date.now() > cached.expiry) {
            this.cache.delete(key);
            return null;
        }

        return cached.data;
    }

    clear(): void {
        this.cache.clear();
    }
}

const cache = new CacheManager();

// ============================================
// DEBOUNCE UTILITY (PREVENTS SPAM)
// ============================================

function debounce<T extends (...args: any[]) => any>(
    func: T,
    wait: number
): (...args: Parameters<T>) => void {
    // FIX: Changed type from NodeJS.Timeout to browser-compatible ReturnType<typeof setTimeout>
    let timeout: ReturnType<typeof setTimeout>;
    return (...args: Parameters<T>) => {
        clearTimeout(timeout);
        timeout = setTimeout(() => func(...args), wait);
    };
}

// ============================================
// BATCH OPERATION QUEUE (REDUCES FIRESTORE CALLS)
// ============================================

class BatchQueue {
    private queue: Array<() => Promise<void>> = [];
    private isProcessing = false;
    private readonly MAX_BATCH = 10;
    private readonly BATCH_DELAY = 1000; // 1 second

    add(operation: () => Promise<void>): void {
        this.queue.push(operation);
        this.processQueue();
    }

    private processQueue = debounce(async () => {
        if (this.isProcessing || this.queue.length === 0) return;

        this.isProcessing = true;
        const batch = this.queue.splice(0, this.MAX_BATCH);

        try {
            await Promise.all(batch.map(op => op().catch(console.error)));
        } finally {
            this.isProcessing = false;
            if (this.queue.length > 0) {
                this.processQueue();
            }
        }
    }, this.BATCH_DELAY);
}

const batchQueue = new BatchQueue();

