            if (!userDoc.exists) {
                // Batch write for new user
                const batch = db.batch();

                batch.set(userRef, {
                    id: userId,
                    name: userName,
                    email: email,
                    joinedAt: firebase.firestore.FieldValue.serverTimestamp(),
                    lastActive: firebase.firestore.FieldValue.serverTimestamp(),
