        const unsubscribe = userFeedbackRef.onSnapshot((doc) => {
            const data = doc.exists 
                ? doc.data() as UserFeedbackData
                : { rating: 0, likedComments: [] };

            cache.set(cacheKey, data, 60000); // 1 minute cache
            callback(data);
        }, (error) => {
            console.warn("⚠️ User feedback error:", error);
            callback(cache.get(cacheKey) || { rating: 0, likedComments: [] });
        });

        return unsubscribe;
    },

    submitRating: async (userId: string, rating: number): Promise<void> => {
        if (!navigator.onLine) throw new Error("You are offline");

        // Validate rating
        if (rating < 1 || rating > 5) {
            throw new Error("Rating must be between 1 and 5");
        }

        try {
            const statsRef = db.collection("feedback_stats").doc("summary");
            const userFeedbackRef = db.collection("users_feedback").doc(userId);

            await db.runTransaction(async (transaction) => {
                const userFeedbackDoc = await transaction.get(userFeedbackRef);

                // Check if already rated
                if (userFeedbackDoc.exists && (userFeedbackDoc.data()?.rating || 0) > 0) {
                    throw new Error("You have already rated");
                }

                const statsDoc = await transaction.get(statsRef);
                const currentStats = statsDoc.exists 
                    ? statsDoc.data() as GlobalStats
                    : { totalRatings: 0, totalRatingSum: 0, totalComments: 0, activeUsers: 0, studyMaterials: 0 };

                // Update stats
                transaction.set(statsRef, {
                    ...currentStats,
                    totalRatings: currentStats.totalRatings + 1,
                    totalRatingSum: currentStats.totalRatingSum + rating,
                    lastUpdated: Date.now()
                }, { merge: true });

                // Update user feedback
                transaction.set(userFeedbackRef, { 
                    rating: rating, 
                    likedComments: userFeedbackDoc.exists ? userFeedbackDoc.data()?.likedComments || [] : []
                }, { merge: true });
            });

            // Clear relevant caches
            cache.clear();

            console.log('✅ Rating submitted');
        } catch (error) {
            console.error('❌ Rating error:', error);
            throw error;
        }
    },

    // ============================================
    // UTILITY: CLEAR CACHE (FORCE REFRESH)
    // ============================================

    clearCache: (): void => {
