const getPlatformInfo = (url: string): { 
    platform: string; 
    icon: string; 
    isYouTube: boolean; 
    isTikTok: boolean; 
    videoId?: string;
    fullUrl?: string;
} => {
    if (!url) return { platform: 'Break', icon: '☕', isYouTube: false, isTikTok: false };

    // Normalize URL
    let cleanUrl = url.trim();
    if (!cleanUrl.startsWith('http')) {
        cleanUrl = `https://${cleanUrl}`;
    }

    try {
        const urlObj = new URL(cleanUrl);
        const hostname = urlObj.hostname.toLowerCase();

        if (hostname.includes('youtube.com') || hostname.includes('youtu.be')) {
            let videoId: string | null = null;
            if (hostname.includes('youtu.be')) {
                videoId = urlObj.pathname.slice(1);
            } else if (urlObj.pathname.includes('/shorts/')) {
                videoId = urlObj.pathname.split('/shorts/')[1].split('?')[0];
            } else {
                videoId = urlObj.searchParams.get('v');
            }
            return { 
                platform: 'YouTube', 
                icon: '▶️', 
                isYouTube: true, 
                isTikTok: false, 
                videoId: videoId || undefined,
                fullUrl: cleanUrl
            };
        }

        if (hostname.includes('tiktok.com')) {
            // Extract video ID from various TikTok URL formats
            const parts = urlObj.pathname.split('/');
            const videoIndex = parts.indexOf('video');
            let videoId: string | undefined;

            if (videoIndex !== -1 && parts.length > videoIndex + 1) {
                videoId = parts[videoIndex + 1].split('?')[0];
            }

            return { 
                platform: 'TikTok', 
                icon: '🎵', 
                isYouTube: false, 
                isTikTok: true, 
                videoId,
                fullUrl: cleanUrl
            };
        }

        if (hostname.includes('instagram.com')) return { platform: 'Instagram', icon: '📸', isYouTube: false, isTikTok: false, fullUrl: cleanUrl };
