                                        <ExternalLinkIcon className="w-6 h-6" />
                                    </button>
                                </>
                            ) : (
                                <div className="text-center">
                                    <div className="text-6xl mb-4 animate-pulse">✨</div>
                                    <p className="text-2xl font-bold text-blue-700 dark:text-blue-300 mb-2">Enjoy your break!</p>
