<content><![CDATA[
// services/notificationService.ts

import type { SmartPlan, NotificationSettings, PlanSlot } from '../../types.ts';

type PendingNotification = {
    id: string;
    title: string;
    options: NotificationOptions;
    triggerTime: number;
};

// A pleasant chime sound in Base64 (MP3 format)
const ALARM_SOUND_BASE64 = "data:audio/mp3;base64,";

class NotificationService {
  private registration: ServiceWorkerRegistration | null = null;
  private pendingTimers: number[] = [];
  private alarmAudio: HTMLAudioElement | null = null;
  private isAudioUnlocked = false;

  constructor() {
    this.init();
    if (typeof window !== 'undefined') {
        window.addEventListener('load', () => this.checkPendingNotifications());

        // Setup audio element
        this.alarmAudio = new Audio(ALARM_SOUND_BASE64);
        this.alarmAudio.volume = 0.5;

        // Unlock audio on ANY user interaction
        const unlockAudio = () => {
            if (!this.isAudioUnlocked && this.alarmAudio) {
                // Play and immediately pause to whitelist the audio element
                this.alarmAudio.play().then(() => {
                    this.alarmAudio?.pause();
                    if (this.alarmAudio) this.alarmAudio.currentTime = 0;
                    this.isAudioUnlocked = true;
                    console.log('✅ Audio unlocked via user interaction');
                }).catch(e => {
                    console.warn('⚠️ Audio unlock blocked:', e);
                });
            }
        };

        window.addEventListener('click', unlockAudio, { once: true });
        window.addEventListener('touchstart', unlockAudio, { once: true });
        window.addEventListener('keydown', unlockAudio, { once: true });

        setInterval(() => this.checkPendingNotifications(), 60 * 1000); // Check every minute
    }
  }

  async init() {
    if ('serviceWorker' in navigator) {
      try {
        this.registration = await navigator.serviceWorker.ready;
        console.log('✅ Service Worker is ready.');
      } catch (error) {
        console.error('❌ Service Worker failed to become ready:', error);
      }
    }
  }

  async requestPermission(): Promise<boolean> {
    if (!('Notification' in window)) {
      return false;
    }

    if (Notification.permission === 'granted') {
      return true;
    }

    const permission = await Notification.requestPermission();
    if (permission === 'granted') {
        this.sendNotification('You\'re all set! 🔔', {
            body: 'EduBlay will now help you stay on track with timely study reminders.',
            requireInteraction: false
        });
        await this.playAlarm(); // Test sound immediately
        return true;
    }

    return false;
  }

  async sendNotification(title: string, options: NotificationOptions = {}): Promise<void> {
    if (Notification.permission !== 'granted') return;

    const defaultOptions: any = {
        icon: "/favicon.ico", // Ensure this exists or use a data URI
        vibrate: [200, 100, 200],
        requireInteraction: true,
        data: {
            url: window.location.href
        }
    };

    const finalOptions = { ...defaultOptions, ...options };

    try {
        if (this.registration && this.registration.showNotification) {
            await this.registration.showNotification(title, finalOptions);
        } else {
            const n = new Notification(title, finalOptions);
            n.onclick = () => {
                window.focus();
                n.close();
            };
        }
        console.log('📬 Notification sent:', title);
    } catch (e) {
        console.error("❌ Error showing notification:", e);
    }
  }

  scheduleNotification(title: string, options: NotificationOptions, triggerTime: number): string {
    const id = `notif-${Date.now()}-${Math.random()}`;
    const notification: PendingNotification = { id, title, options, triggerTime };

    this.savePendingNotification(notification);
    this.scheduleTimer(notification);
    return id;
  }

  // Plays a distinct sound when a session/break ends
  async playAlarm() {
    console.log('🔔 playAlarm() called');

    if (this.alarmAudio) {
        try {
            this.alarmAudio.currentTime = 0;
            await this.alarmAudio.play();
            console.log('✅ Alarm sound played successfully');
        } catch (e) {
            console.error("❌ Audio playback failed (blocked by browser?):", e);
            // Fallback: Try AudioContext beep if HTML5 Audio fails
            this.playFallbackBeep();
        }
    }
  }

  private playFallbackBeep() {
    try {
        const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
        if (!AudioContextClass) return;
        const ctx = new AudioContextClass();
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.connect(gain);
        gain.connect(ctx.destination);
        osc.frequency.value = 880;
        gain.gain.value = 0.1;
        osc.start();
        setTimeout(() => osc.stop(), 500);
    } catch (e) {
        console.error("Fallback beep failed", e);
    }
  }

  private scheduleTimer(notification: PendingNotification) {
    const now = Date.now();
    const delay = notification.triggerTime - now;

    if (delay > 0) {
        const timerId = window.setTimeout(() => {
            this.sendNotification(notification.title, notification.options);
            this.playAlarm();
            this.removePendingNotification(notification.id);
        }, delay);
        this.pendingTimers.push(timerId);
    } else {
        this.sendNotification(notification.title, notification.options);
        this.playAlarm();
    }
  }

  private savePendingNotification(notification: PendingNotification) {
    const pending = this.getPendingNotifications();
    const updated = [...pending.filter(n => n.id !== notification.id), notification];
    localStorage.setItem('pendingNotifications', JSON.stringify(updated));
  }

  private removePendingNotification(id: string) {
    const pending = this.getPendingNotifications();
    const updated = pending.filter(n => n.id !== id);
    localStorage.setItem('pendingNotifications', JSON.stringify(updated));
  }

  private getPendingNotifications(): PendingNotification[] {
      try {
        return JSON.parse(localStorage.getItem('pendingNotifications') || '[]');
      } catch {
        return [];
      }
  }

  checkPendingNotifications() {
    const pending = this.getPendingNotifications();
    const now = Date.now();
    const remaining: PendingNotification[] = [];

    this.pendingTimers.forEach(clearTimeout);
    this.pendingTimers = [];

    pending.forEach(notif => {
      if (notif.triggerTime <= now) {
        this.sendNotification(notif.title, notif.options);
        this.playAlarm();
      } else {
        remaining.push(notif);
        this.scheduleTimer(notif);
      }
    });

    localStorage.setItem('pendingNotifications', JSON.stringify(remaining));
  }

  cancelAllNotifications() {
    this.pendingTimers.forEach(clearTimeout);
    this.pendingTimers = [];
    localStorage.removeItem('pendingNotifications');
  }

  // Debugging tool
  async testAlarm() {
      console.log("🧪 Testing alarm...");
      await this.playAlarm();
  }
}

export const notificationService = new NotificationService();
