const getPlatformInfo = (url: string): { 
    platform: string; 
    icon: string; 
    isYouTube: boolean; 
    isTikTok: boolean; 
    videoId?: string;
    fullUrl?: string;
} => {
    if (!url) return { platform: 'Break', icon: '☕', isYouTube: false, isTikTok: false };

    // Normalize URL
    let cleanUrl = url.trim();
    if (!cleanUrl.startsWith('http')) {
        cleanUrl = `https://${cleanUrl}`;
    }

    try {
        const urlObj = new URL(cleanUrl);
        const hostname = urlObj.hostname.toLowerCase();

        if (hostname.includes('youtube.com') || hostname.includes('youtu.be')) {
            let videoId: string | null = null;
            if (hostname.includes('youtu.be')) {
                videoId = urlObj.pathname.slice(1);
            } else if (urlObj.pathname.includes('/shorts/')) {
                videoId = urlObj.pathname.split('/shorts/')[1].split('?')[0];
            } else {
                videoId = urlObj.searchParams.get('v');
            }
            return { 
                platform: 'YouTube', 
                icon: '▶️', 
                isYouTube: true, 
                isTikTok: false, 
                videoId: videoId || undefined,
                fullUrl: cleanUrl
            };
        }

        if (hostname.includes('tiktok.com')) {
            // Extract video ID from various TikTok URL formats
            const parts = urlObj.pathname.split('/');
            const videoIndex = parts.indexOf('video');
            let videoId: string | undefined;

            if (videoIndex !== -1 && parts.length > videoIndex + 1) {
                videoId = parts[videoIndex + 1].split('?')[0];
            }

            return { 
                platform: 'TikTok', 
                icon: '🎵', 
                isYouTube: false, 
                isTikTok: true, 
                videoId,
                fullUrl: cleanUrl
            };
        }

        if (hostname.includes('instagram.com')) return { platform: 'Instagram', icon: '📸', isYouTube: false, isTikTok: false, fullUrl: cleanUrl };
        if (hostname.includes('spotify.com')) return { platform: 'Spotify', icon: '🎧', isYouTube: false, isTikTok: false, fullUrl: cleanUrl };
        if (hostname.includes('netflix.com')) return { platform: 'Netflix', icon: '🍿', isYouTube: false, isTikTok: false, fullUrl: cleanUrl };
        if (hostname.includes('twitch.tv')) return { platform: 'Twitch', icon: '🎮', isYouTube: false, isTikTok: false, fullUrl: cleanUrl };

    } catch (e) {
        console.error('URL parsing error:', e);
    }

    return { platform: 'Web', icon: '🌐', isYouTube: false, isTikTok: false, fullUrl: cleanUrl };
};

// TikTok Embed Component with multiple fallback methods
const TikTokEmbed: React.FC<{ videoId: string; fullUrl: string }> = ({ videoId, fullUrl }) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const [embedMethod, setEmbedMethod] = useState<'iframe' | 'blockquote' | 'direct'>('iframe');
    const [embedError, setEmbedError] = useState(false);

    useEffect(() => {
        // Try loading TikTok embed script for blockquote method
        const script = document.createElement('script');
        script.src = 'https://www.tiktok.com/embed.js';
        script.async = true;
        script.onload = () => {
            console.log('TikTok embed script loaded successfully');
        };
        script.onerror = () => {
            console.error('Failed to load TikTok embed script');
            setEmbedError(true);
        };
        document.body.appendChild(script);

        return () => {
            // Cleanup script on unmount
            if (document.body.contains(script)) {
                document.body.removeChild(script);
            }
        };
    }, []);

    const handleIframeError = () => {
        console.log('Iframe method failed, trying blockquote method');
        setEmbedMethod('blockquote');
    };

    const handleOpenDirect = () => {
        window.open(fullUrl, '_blank', 'width=400,height=800');
    };

    if (embedError) {
        return (
            <div className="flex flex-col items-center justify-center p-12 bg-gradient-to-br from-pink-50 to-purple-50 dark:from-pink-900/20 dark:to-purple-900/20 rounded-2xl border-2 border-pink-200 dark:border-pink-800 shadow-inner h-full">
                <div className="text-6xl mb-6">🎵</div>
                <p className="text-xl text-pink-800 dark:text-pink-300 mb-8 font-semibold text-center">
