                <button 
                    onClick={handleOpenDirect}
                    className="py-4 px-10 bg-gradient-to-r from-pink-600 to-purple-600 hover:from-pink-700 hover:to-purple-700 text-white rounded-2xl font-bold shadow-2xl transition-all transform hover:scale-105 flex items-center justify-center gap-3 text-lg"
