                    <span>Open TikTok Video</span>
                    <ExternalLinkIcon className="w-6 h-6" />
                </button>
                <p className="text-sm text-gray-500 mt-4 text-center max-w-md">
                    Due to TikTok's embed restrictions, videos open in a new window for the best viewing experience.
                </p>
            </div>
        );
    }

    return (
        <div ref={containerRef} className="w-full h-full flex justify-center items-center bg-black rounded-2xl overflow-hidden">
            {embedMethod === 'iframe' && (
                <div className="relative h-full w-full max-w-[400px]">
                    <iframe
                        src={`https://www.tiktok.com/embed/v2/${videoId}`}
                        className="w-full h-full"
                        allow="encrypted-media; fullscreen"
                        allowFullScreen
                        scrolling="no"
                        style={{ 
                            border: 'none',
                            maxHeight: '100%',
                            aspectRatio: '9/16'
                        }}
                        title="TikTok Video"
                        onError={handleIframeError}
                    />
                </div>
            )}

            {embedMethod === 'blockquote' && (
                <div className="w-full h-full flex items-center justify-center p-4">
                    <blockquote 
                        className="tiktok-embed" 
                        cite={fullUrl}
                        data-video-id={videoId}
                        style={{ 
                            maxWidth: '605px', 
                            minWidth: '325px',
                            margin: '0 auto'
                        }}
                    >
                        <section>
                            <a 
                                target="_blank" 
                                rel="noopener noreferrer"
                                href={fullUrl}
                                className="text-white hover:text-blue-400"
                            >
                                View on TikTok
                            </a>
                        </section>
                    </blockquote>
                </div>
            )}

            {/* Fallback button */}
            <button
                onClick={handleOpenDirect}
                className="absolute bottom-4 right-4 z-50 px-4 py-2 bg-pink-600 hover:bg-pink-700 text-white text-sm rounded-lg shadow-lg transition-all flex items-center gap-2"
            >
                Open in TikTok
                <ExternalLinkIcon className="w-4 h-4" />
